import numpy as np
from mpmath import mp, mpf
from copy import deepcopy
from functools import singledispatchmethod

class CubeSphereGapTransform:
    def __init__(self, inner_limit, outer_limit):
        self.__inner_limit = inner_limit
        self.__outer_limit = outer_limit

    @singledispatchmethod
    def transform(self, points, _):
        raise TypeError(f"Unsupported input type: {type(points).__name__}")
    
    # Limited transform, assumes [0,1]^d input
    # Method generated by OpenAI Astra 6.0 Max from provided C++ code
    @transform.register(np.ndarray)
    def _np_transform(
        self, points, weights
    ):
        u = np.asarray(points, dtype=np.float64)
        w = np.asarray(weights, dtype=np.float64)
        A = self.__inner_limit
        B = self.__outer_limit
        k, d = u.shape

        delta = B - A
        t = A + delta * u[:, 0]

        v = np.ones((k, d), dtype=np.float64)
        v[:, 1:] = 2.0 * u[:, 1:] - 1.0
        a = np.sqrt(d) / np.linalg.norm(v, axis=1) - 1.0

        # F_a(F_b(u)) = h*v.
        s = 1.0 + u[:, 0] * a
        h = t * s
        dh_du0 = delta * s + t * a
        jacobian = (2.0 * h) ** (d - 1) * dh_du0

        y = h[:, None] * v
        out = np.empty((2 * d, k, d), dtype=np.float64)
        out[0] = y

        # Positive faces: exactly the sequential rotations in the C++ code.
        for i in range(d - 1):
            y[:, [i, i + 1]] = y[:, [i + 1, i]] * [-1.0, 1.0]
            out[i + 1] = y

        # Move from the last positive face to the first negative face.
        y[:, [0, d - 1]] = y[:, [d - 1, 0]] * [-1.0, 1.0]
        out[d] = y

        # Remaining negative faces.
        for i in range(d - 1):
            y[:, [i, i + 1]] = y[:, [i + 1, i]] * [-1.0, 1.0]
            out[d + i + 1] = y

        adjusted_weights = np.tile(w * jacobian, 2 * d)
        return out.reshape(2 * d * k, d), adjusted_weights

# Transform only first 3 coordinates, leaving 4-th as is
class TruncatedGapTransform:
    def __init__(self, transform):
        self.gap_transform = transform
    @singledispatchmethod
    def transform(self, points, _):
        raise TypeError(f"Unsupported input type: {type(points).__name__}")

    @transform.register(np.ndarray)
    def _np_transform(self, points, weights):
        trans_points, trans_weights = self.gap_transform.transform(points[:,:-1], weights)
        translated_coord = np.tile(points[:,-1], 2 * (points.shape[1]-1))
        return np.hstack([trans_points, translated_coord[:,None]]), trans_weights

class SphericalToCarthesianTransform:
    def __init__(self, origin_offset):
        self.__origin_offset = origin_offset
        self.__d = len(origin_offset)

    @singledispatchmethod
    def transform(self, points, _):
        raise TypeError(f"Unsupported input type: {type(points).__name__}")

    @transform.register(np.ndarray)
    def _np_transform(self, points, weights):
        d = self.__d
        carth = np.ones(points.shape)*points[:,0][:, None]
        J = points[:,0]**(d-1)
        for i in range(1, d):
            inv_i = d-i
            if inv_i > 1:
                J *= np.sin((points[:,i]))**(d-i-1)
                carth[:, inv_i] *= np.cos(points[:,i])
                carth[:, :inv_i] *= np.sin(points[:,i])[:, None]
            else:
                carth[:, 1] *= np.sin(points[:,i])
                carth[:, 0] *= np.cos(points[:,i])

        return carth + self.__origin_offset, weights*J

    # we assume that thigh is list of mpf objects
    @transform.register(list)
    def _high_prec_transform(self, points, weights):
        d = self.__d
        carth = []
        J = []
        for i in range(len(points)):
            carth.append([points[i][0] for _ in range(d)])
            J.append(weights[i]*mp.power(points[i][0], d-1))
            for j in range(1, d):
                inv_j = d-j
                if inv_j > 1:
                    J[i] *= mp.power(mp.sin(points[i][j]),(d-j-1))
                    carth[i][inv_j] *= mp.cos(points[i][j])
                    for k in range(inv_j):
                        carth[i][k] *= mp.sin(points[i][j])
                else:
                    carth[i][1] *= mp.sin(points[i][j])
                    carth[i][0] *= mp.cos(points[i][j])
            for k in range(d):
                carth[i][k] += self.__origin_offset[k]
        return carth, J

class SphericalToCarthesianJacobianOnlyTransform:
    @singledispatchmethod
    def transform(self, points, _):
        raise TypeError(f"Unsupported input type: {type(points).__name__}")

    @transform.register(np.ndarray)
    def _np_transform(self, points, weights):
        d = len(points[0])
        J = points[:,0]**(d-1)
        for i in range(1, d-1):
            inv_i = d-i
            J *= np.sin((points[:,i]))**(d-i-1)

        return points, weights*J

    # we assume that thigh is list of mpf objects
    @transform.register(list)
    def _high_prec_transform(self, points, weights):
        d = len(points[0])
        J = []
        for i in range(len(points)):
            J.append(weights[i]*mp.power(points[i][0], d-1))
            for j in range(1, d-1):
                inv_j = d-j
                J[i] *= mp.power(mp.sin(points[i][j]),(d-j-1))
        return points, J

class ResidualTransform:
    def __init__(self,
        cutoff,
        origin_offset = np.array([0,0,0]),
        jacobian_only = False):
        self.__origin_offset = origin_offset
        self.__cutoff = cutoff
        if not jacobian_only:
            self.__spherical_transform = SphericalToCarthesianTransform(origin_offset)
        else:
            self.__spherical_transform =SphericalToCarthesianJacobianOnlyTransform()
        self.__d = len(origin_offset)

    @singledispatchmethod
    def transform(self, points, _):
        raise TypeError(f"Unsupported input type: {type(points).__name__}")

    @transform.register(np.ndarray)
    def _np_transform(self, points, weights):
        points_inverted = points.copy()
        points_inverted[:,0] = self.__cutoff/(1-points[:,0])
        return self.__spherical_transform.transform(
            points_inverted,
            weights*self.__cutoff/(1-points[:,0])**2)

# Transform only first 3 coordinates, leaving 4-th as is
class TruncatedResidualTransform:
    def __init__(self, transform):
        self.residual_transform = transform
    @singledispatchmethod
    def transform(self, points, _):
        raise TypeError(f"Unsupported input type: {type(points).__name__}")

    @transform.register(np.ndarray)
    def _np_transform(self, points, weights):
        trans_points, trans_weights = self.residual_transform.transform(points[:,:-1], weights)
        return np.hstack([trans_points, points[:,-1,None]]), trans_weights

class AffineCubeTransform:
    def __init__(self, lp, ext):
        self.__lp = lp
        self.__ext = ext

    @singledispatchmethod
    def transform(self, points, _):
        raise TypeError(f"Unsupported input type: {type(points).__name__}")

     # Limited transform, assumes [0,1]^d input
    @transform.register(np.ndarray)
    def _np_transform(self, points, weights):
        return points*self.__ext + self.__lp, weights * np.prod(self.__ext)

# Special transform for surfaces, tiles the space |><|>
class TrippleTiledSurfaceTransform:
    def __init__(self, thresh_radius):
        self.__radius = thresh_radius


    @singledispatchmethod
    def transform(self, points, _):
        raise TypeError(f"Unsupported input type: {type(points).__name__}")

    @transform.register(list)
    def _np_transform(self, points, weights):
        left_points = deepcopy(points)
        right_points = deepcopy(points)
        for i in range(len(points)):
            left_points[i][0] = self.__radius - left_points[i][0]
            right_points[i][0] = self.__radius + right_points[i][0]

        return points + left_points + right_points, weights + weights + weights

# Special transform to integrate imaginary part of threshold singularity
class ThresholdImaginaryTransform:
    def __init__(self, thresh_radius):
        self.__radius = thresh_radius
        self.__spherical_transform = SphericalToCarthesianTransform([mpf("0"), mpf("0"),  mpf("0")])

    # Only supported for high precision integration
    @singledispatchmethod
    def transform(self, points, _):
        raise TypeError(f"Unsupported input type: {type(points).__name__}")

    @transform.register(list)
    def _np_transform(self, points, weights):
        points_offset = []
        offset = mpf('0.0000000000000000001')
        r = self.__radius + offset
        for i in range(len(points)):
            points_offset.append([r, *points[i]])
            weights[i] *= offset * mp.pi

        return self.__spherical_transform.transform(points_offset, weights)